def get_curated_samples(datatype: Optional[str] = None) -> List[Dict[str, Any]]:
    """
    Retrieve curated samples.
    If datatype is provided ('discharge', 'pathology', 'radiology'), returns 5 samples.
    Otherwise returns all 15 samples flattened.
    """
    if datatype:
        dt = datatype.lower()
        if dt not in CURATED_SAMPLES:
            raise ValueError(f"Unknown datatype: {datatype}. Choose from {list(CURATED_SAMPLES.keys())}")
        return list(CURATED_SAMPLES[dt])
    
    flattened = []
    for dt_samples in CURATED_SAMPLES.values():
        flattened.extend(dt_samples)
    return flattened

def get_sample_by_id(sample_id: str) -> Optional[Dict[str, Any]]:
    """Retrieve a single sample by its unique sample_id (e.g. 'DS-01', 'PATH-03', 'RAD-02')."""
    for samples in CURATED_SAMPLES.values():
        for s in samples:
            if s.get('sample_id') == sample_id:
                return s
    return None
